const b = $input.first().json.body || $input.first().json;
const ranges = { '2': 48, '3': 75 };
const min = ranges[String(b.bhk)] || 48;
const budget = Number(b.budget_lakh || 0);
const months = Number(b.timeline_months ?? 99);
const finance = String(b.finance || '');
const visit = b.visit === true || String(b.visit).toLowerCase() === 'yes';

let pts = 0;
const why = [];
if (budget >= min * 0.95) { pts += 30; why.push('budget fits'); }
else if (budget >= min * 0.8) { pts += 15; why.push('budget close'); }
if (months <= 3) { pts += 30; why.push('buying within 3 months'); }
else if (months <= 6) { pts += 20; why.push('within 6 months'); }
else if (months <= 12) { pts += 10; why.push('within a year'); }
if (finance === 'Loan pre-approved' || finance === 'Self-funded') { pts += 20; why.push('money ready'); }
else if (finance === 'Loan needed') { pts += 10; why.push('loan needed'); }
if (visit) { pts += 20; why.push('agreed to site visit'); }

const cls = pts >= 70 ? 'HOT' : pts >= 40 ? 'WARM' : 'COLD';
const next = cls === 'HOT' ? 'Call within 15 min, confirm visit' : cls === 'WARM' ? 'WhatsApp follow-up in 24 h' : 'Add to monthly nurture list';

return [{ json: {
  Time: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
  Name: b.name || 'Unknown',
  Phone: b.phone || '',
  Need: (b.bhk || '?') + ' BHK',
  Budget_Lakh: budget,
  Timeline_Months: months,
  Payment: finance,
  Site_Visit: visit ? 'Yes' : 'No',
  Score: pts,
  Class: cls,
  Reason: why.join(', '),
  Next_Action: next
} }];

